/* C API of the Rust port of `div64.c`, generated by rust-anything. */
#ifndef DIV64_RS_H
#define DIV64_RS_H

#include <stdbool.h>
#include <stddef.h>
#include <stdint.h>
#include <sys/types.h>

uint64_t mul_u64_add_u64_div_u64(uint64_t a, uint64_t b, uint64_t c, uint64_t d);

/* Manual addition (pointer out-param kept it outside the bridge). */
uint32_t iter_div_u64_rem(uint64_t dividend, uint32_t divisor, uint64_t *remainder);

/* The same functions under `rust_anything_` names, for shadow runs. */
uint64_t rust_anything_mul_u64_add_u64_div_u64(uint64_t a, uint64_t b, uint64_t c, uint64_t d);
uint32_t rust_anything_iter_div_u64_rem(uint64_t dividend, uint32_t divisor, uint64_t *remainder);

#endif /* DIV64_RS_H */
